		t.Errorf("/health expected 200, got %d", resp.StatusCode)
	}

	// Test /metrics
	resp, err = http.Get(server.URL + "/metrics")
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Errorf("/metrics expected 200, got %d", resp.StatusCode)
	}
}
